import{_ as n,l as o,o as a,c as i,v as d,p as c,x as t,d as l,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"dentry 缓存","description":"","frontmatter":{"title":"dentry 缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dcache.md","filePath":"cs/dcache.md","lastUpdated":1789023840000}'),p={name:"cs/dcache.md"};function m(_,e,E,u,f,A){const r=o("Mermaid");return a(),i("div",null,[e[1]||(e[1]=d('<h1 id="dentry-缓存" tabindex="-1">dentry 缓存 <a class="header-anchor" href="#dentry-缓存" aria-label="Permalink to &quot;dentry 缓存&quot;">​</a></h1><div class="epigraph"><p>目录项把「父目录 + 分量名」缓存成指向 inode 的内存对象；命中则不必再读目录块。</p><footer>—— 据 McKusick 等对 BSD namei 的讨论；Linux VFS 对 dentry 的整理</footer></div><p><a href="/cs/file-table">上一课</a>让 fd 抓住打开实例，路径仍是字符串。每次 <code>open</code> 若都从根把目录文件扫一遍，同样的 <code>/usr/lib</code> 会把磁盘打爆。<a href="/cs/memory-reclaim">内存回收</a> 已允许收缩这类缓存。缺口是 <strong>dentry</strong>：负缓存（没有这个名字）也要记住，以免重复确认不存在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>路径查找是「父 inode + 名 → 子 inode」。目录块在盘上；热点名应在 RAM。dentry 持有名、父指针、子哈希、指向 inode 的指针（或负项）。缺口不是 inode 磁盘布局——下一课才讲持久 inode——而是内存里的名字图，以及与页 Cache 的分工：页 Cache 缓存文件数据页；dcache 缓存目录关系。</p><p>本课不把 RCU 查找的全部锁级写完。</p><p><span class="marginnote">哈希键通常是父 dentry 加名。卸载与 rmdir 必须使 dentry 失效。shrinker 可以丢未使用的 dentry，释放 slab 页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找分量：在父的哈希中找 dentry。命中正项则得到 inode 指针；命中负项则 ENOENT。未命中则读目录（下一课的目录文件），插入 dentry。<code>.</code> 与 <code>..</code> 可走父指针，少一次哈希。与打开文件表的关系：<code>open</code> 成功后 fd 抓住 inode/file，dentry 仍可被其他查找共享。</p>',9)),(a(),c(h,null,{default:t(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E7%88%B6%20%2B%20%E5%88%86%E9%87%8F%E5%90%8D%22%5D%20--%3E%20HASH%5B%22dentry%20%E5%93%88%E5%B8%8C%22%5D%0A%20%20HASH%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%3A%20inode%20%E6%88%96%E8%B4%9F%E9%A1%B9%22%5D%0A%20%20HASH%20--%3E%20MISS%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%3A%20%E8%AF%BB%E7%9B%AE%E5%BD%95%E5%9D%97%22%5D%0A%20%20MISS%20--%3E%20INS%5B%22%E6%8F%92%E5%85%A5%20dentry%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=d('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>dcache 把路径的局部性变成 O(1) 平均查找，让编译器反复 <code>stat</code> 头文件不必每次下盘。它依赖 slab 分配 dentry 对象，回收时是 shrinker 的主要客户之一。不要把 dentry 当成用户可见的硬链接计数；硬链接是持久 inode 上的 nlink，下一课。</p><p><a href="/cs/vfs">VFS</a> 会把 lookup 做成操作表；本课先承认缓存对象存在。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入网络文件系统上 dentry 超时失效的全部协议。不保证负缓存在所有一致性模型下永久正确——NFS 等会到期。下一课给出盘上 inode 与目录文件的真实含义，查找算法才能说完。</p><p>后课默认：名字可以命中内存项。盘上「是什么」与「叫什么」如何分离，下一课 inode 与目录。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>dentry 缓存父+名到 inode；负项缓存不存在。</li><li>与页 Cache 分工：关系对数据。</li><li>持久 inode 布局是下一课。</li><li>出处：McKusick et al., <em>4.4BSD</em>；Linux VFS 概述；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const y=n(p,[["render",m]]);export{B as __pageData,y as default};
